ruleBookInfo.init:
@js:
$ = (_) => java.getString(_);
({
    n: $(".booktitle@text"),
    a: $("[property$=author]@content"),
    k: $("[property~=category|status|update_time]@content"),
    w: $("text.字数@text\#\#字数[：:]"),
    l: $("[property~=las?test_chapter_name]@content"),
    i: $("[property$=description]@content"),
    c: $("[property$=image]@content"),
    t: $("text.目录@href"),
    d: $("text.下载@href")
});

ruleContent.content:
@js:
var html = String(result);
var m = html.match(/var player_aaaa=(\{[\s\S]*?\})\s*<\/script>/);
if (!m) {
    m = html.match(/var player_aaaa=(\{[\s\S]*?\})/);
}
if (m) {
    try {
        var data = JSON.parse(m[1]);
        result = data.url || '';
    } catch (e) {
        var u = m[1].match(/"url"\s*:\s*"([^"]+)"/);
        result = u ? u[1] : '';
    }
} else {
    var u2 = html.match(/"url"\s*:\s*"([^"]+)"/);
    result = u2 ? u2[1] : '';
}
result = String(result).replace(/\\\//g, '/');
result

